//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 480
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'
import { getScene, SCENE_AOD } from '@zos/app'
import { Step } from '@zos/sensor'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Hour_gjem = [
  A('time_30.png'),
  A('time_31.png'),
  A('time_32.png'),
  A('time_33.png'),
  A('time_34.png'),
  A('time_35.png'),
  A('time_36.png'),
  A('time_37.png'),
  A('time_38.png'),
  A('time_39.png'),
]

const img_Steps_ui6f = [
  A('font_2_30.png'),
  A('font_2_31.png'),
  A('font_2_32.png'),
  A('font_2_33.png'),
  A('font_2_34.png'),
  A('font_2_35.png'),
  A('font_2_36.png'),
  A('font_2_37.png'),
  A('font_2_38.png'),
  A('font_2_39.png'),
]

WatchFace({
  initView() {
    const scene = getScene()
    const aod = scene === SCENE_AOD

    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(480),
      h: px(480),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONAL_AOD,
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(106),
      hour_startY: px(144),
      hour_zero: 0,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_gjem,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONAL_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(240),
      y: px(159),
      src: A('colon_3a.png'),
      show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONAL_AOD
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(254),
      minute_startY: px(144),
      minute_zero: 0,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_gjem,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONAL_AOD,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(120),
      y: px(298),
      type: ui.data_type.STEP,
      font_array: img_Steps_ui6f,
      h_space: px(2),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(180),
      y: px(355),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Steps_ui6f,
      h_space: px(2),
      align_h: ui.align.LEFT,
      unit_en: A('unit_b0.png'),
      unit_sc: A('unit_b0.png'),
      unit_tc: A('unit_b0.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Step arc (ARC_PROGRESS)
    const w_Step_arc_zrvk = ui.createWidget(ui.widget.ARC_PROGRESS, {
      center_x: px(240),
      center_y: px(240),
      radius: px(192),
      start_angle: -220,
      end_angle: 40,
      line_width: px(10),
      color: 0x34e073,
      level: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })
    // Steps progress (Step.getCurrent)
    const s_step = new Step()
    const upd_Step_arc_zrvk = () => {
      const value = s_step.getCurrent()
      const target = s_step.getTarget() || 1
      w_Step_arc_zrvk.setProperty(ui.prop.LEVEL, Math.min(100, Math.round((value / target) * 100)))
    }
    s_step.onChange(upd_Step_arc_zrvk)
    upd_Step_arc_zrvk()

    // Steps label (TEXT)
    ui.createWidget(ui.widget.TEXT, {
      x: px(130),
      y: px(413),
      w: px(220),
      h: px(44),
      color: 0x9fb0c8,
      text_size: px(30),
      align_h: ui.align.CENTER_H,
      align_v: ui.align.CENTER_V,
      text: "STEPS",
      font: "fonts/Orbitron-Bold.ttf",
      show_level: ui.show_level.ONLY_NORMAL,
    })

  },

  build() {
    this.initView()
  },
})
